'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['DecimalDial']);
const { DecimalDial } = api;

const options = { min: -2, max: 3, step: 0.25, precision: 2 };
const dial = new DecimalDial('3.50', options);
assert.equal(dial.getValue(), 3);
assert.deepEqual(options, { min: -2, max: 3, step: 0.25, precision: 2 });
assert.equal(dial.setValue('.25'), 0.25);
assert.equal(dial.getValue(), 0.25);
assert.equal(dial.setValue('-2'), -2);
assert.equal(dial.setValue(50), 3);
assert.equal(dial.setValue(-50), -2);
assert.equal(dial.setValue(-0), 0);
assert.equal(Object.is(dial.getValue(), -0), false);

for (const value of ['', ' ', ' 2', '2 ', '1e2', '0x10', '2x', '.', '+', '--1', NaN, Infinity, -Infinity, null, undefined, {}, []]) {
  assert.throws(() => dial.setValue(value), TypeError);
}
for (const badOptions of [undefined, null, {}, { min: 0, max: 1, step: 1 }, { min: 0, max: 1, step: 1, precision: -1 }, { min: 0, max: 1, step: 1, precision: 11 }, { min: 0, max: 1, step: 1, precision: 1.5 }, { min: 2, max: 1, step: 1, precision: 0 }, { min: 0, max: 1, step: 0, precision: 0 }, { min: 0, max: 1, step: -1, precision: 0 }, { min: NaN, max: 1, step: 1, precision: 0 }, { min: 0, max: Infinity, step: 1, precision: 0 }]) {
  assert.throws(() => new DecimalDial(0, badOptions), TypeError);
}
assert.throws(() => new DecimalDial('bad', options), TypeError);

const zeroOutside = new DecimalDial(0, { min: 1, max: 2, step: 0.25, precision: 2 });
assert.equal(zeroOutside.getValue(), 0);
assert.equal(zeroOutside.setValue('0.00'), 0);
assert.equal(zeroOutside.increment(), 1);
assert.equal(zeroOutside.decrement(), 1);

const observed = [];
const notifying = new DecimalDial(0, { min: -1, max: 1, step: 0.25, precision: 2 });
let unsubscribeFirst;
unsubscribeFirst = notifying.subscribe((event) => {
  observed.push(['first', event]);
  unsubscribeFirst();
});
const secondEvents = [];
const unsubscribeSecond = notifying.subscribe((event) => secondEvents.push(event));
assert.equal(notifying.increment(), 0.25);
assert.equal(notifying.increment(), 0.5);
assert.equal(notifying.decrement(), 0.25);
assert.equal(observed.length, 1);
assert.equal(secondEvents.length, 3);
assert.deepEqual(secondEvents.map((event) => event.type), ['increment', 'increment', 'decrement']);
assert.deepEqual(secondEvents.map((event) => event.value), [0.25, 0.5, 0.25]);
for (const event of [observed[0][1], ...secondEvents]) assert.equal(Object.isFrozen(event), true);
assert.notStrictEqual(observed[0][1], secondEvents[0]);
assert.notStrictEqual(secondEvents[0], secondEvents[1]);
unsubscribeSecond();
notifying.increment();
assert.equal(secondEvents.length, 3);
assert.throws(() => notifying.subscribe(1), TypeError);

const clamped = new DecimalDial(1, { min: 0, max: 1, step: 0.5, precision: 1 });
let calls = 0;
clamped.subscribe(() => calls++);
assert.equal(clamped.increment(), 1);
assert.equal(calls, 0);
assert.equal(clamped.decrement(), 0.5);
assert.equal(calls, 1);
clamped.destroy();
clamped.destroy();
assert.equal(clamped.getValue(), 0.5);
for (const operation of [() => clamped.setValue(0), () => clamped.increment(), () => clamped.decrement(), () => clamped.subscribe(() => {})]) {
  assert.throws(operation, Error);
}

